describe('updateLineItems', () => {
  let mockBase: any;
  let mockTable: any;
  let mockUpdate: jest.Mock;

  beforeEach(() => {
    mockUpdate = jest.fn();
    mockTable = jest.fn(() => ({
      update: mockUpdate,
    }));
    mockBase = jest.fn((tableName: string) => mockTable(tableName));

    (Airtable as any).mockImplementation(() => ({
      base: () => mockBase,
    }));
  });

  it('successfully updates line items with frequency changes', async () => {
    const mockUpdatedRecords = [
      {
        id: 'rec1',
        fields: {
          'Service': 'Lawn Mowing',
          'A la Carte Rate': 100,
          'Handld Rate': 70,
          'Chosen Frequency': 4,
        },
      },
      {
        id: 'rec2',
        fields: {
          'Service': 'Pool Cleaning',
          'A la Carte Rate': 150,
          'Handld Rate': 105,
          'Chosen Frequency': 2,
        },
      },
    ];

    mockUpdate.mockResolvedValue(mockUpdatedRecords);

    const updates = [
      { id: 'rec1', chosenFrequency: 4 },
      { id: 'rec2', chosenFrequency: 2 },
    ];

    const result = await updateLineItems(updates);

    // Verify correct table was called
    expect(mockBase).toHaveBeenCalledWith('Quote Line Items');

    // Verify update was called with correct format
    expect(mockUpdate).toHaveBeenCalledWith([
      {
        id: 'rec1',
        fields: {
          'Chosen Frequency': 4,
        },
      },
      {
        id: 'rec2',
        fields: {
          'Chosen Frequency': 2,
        },
      },
    ]);

    // Verify returned data is correctly mapped
    expect(result).toEqual([
      {
        id: 'rec1',
        service: 'Lawn Mowing',
        alaCarteRate: 100,
        handldRate: 70,
        chosenFrequency: 4,
        requestLink: undefined,
      },
      {
        id: 'rec2',
        service: 'Pool Cleaning',
        alaCarteRate: 150,
        handldRate: 105,
        chosenFrequency: 2,
        requestLink: undefined,
      },
    ]);
  });

  it('handles empty update array', async () => {
    const result = await updateLineItems([]);

    expect(mockUpdate).not.toHaveBeenCalled();
    expect(result).toEqual([]);
  });

  it('filters out updates without frequency changes', async () => {
    const mockUpdatedRecord = [
      {
        id: 'rec1',
        fields: {
          'Service': 'Lawn Mowing',
          'A la Carte Rate': 100,
          'Handld Rate': 70,
          'Chosen Frequency': 3,
        },
      },
    ];

    mockUpdate.mockResolvedValue(mockUpdatedRecord);

    const updates = [
      { id: 'rec1', chosenFrequency: 3 },
      { id: 'rec2', chosenFrequency: undefined }, // Should be filtered out
      { id: 'rec3' }, // Should be filtered out
    ];

    const result = await updateLineItems(updates);

    // Verify only valid updates were sent
    expect(mockUpdate).toHaveBeenCalledWith([
      {
        id: 'rec1',
        fields: {
          'Chosen Frequency': 3,
        },
      },
    ]);

    expect(result).toHaveLength(1);
    expect(result[0].chosenFrequency).toBe(3);
  });

  it('handles Airtable API errors', async () => {
    const apiError = new Error('Airtable API Error: Invalid request');
    mockUpdate.mockRejectedValue(apiError);

    const updates = [{ id: 'rec1', chosenFrequency: 2 }];

    await expect(updateLineItems(updates)).rejects.toThrow('Airtable API Error: Invalid request');

    // Verify error was logged
    const consoleSpy = jest.spyOn(console, 'error').mockImplementation();
    try {
      await updateLineItems(updates);
    } catch (e) {
      // Expected to throw
    }
    expect(consoleSpy).toHaveBeenCalledWith('Error updating line items:', apiError);
    consoleSpy.mockRestore();
  });

  it('handles network errors', async () => {
    const networkError = new Error('Network error: Connection refused');
    mockUpdate.mockRejectedValue(networkError);

    const updates = [{ id: 'rec1', chosenFrequency: 5 }];

    await expect(updateLineItems(updates)).rejects.toThrow('Network error: Connection refused');
  });

  it('correctly maps frequency 0 as a valid update', async () => {
    const mockUpdatedRecord = [
      {
        id: 'rec1',
        fields: {
          'Service': 'Lawn Mowing',
          'A la Carte Rate': 100,
          'Handld Rate': 70,
          'Chosen Frequency': 0,
        },
      },
    ];

    mockUpdate.mockResolvedValue(mockUpdatedRecord);

    const updates = [{ id: 'rec1', chosenFrequency: 0 }];

    const result = await updateLineItems(updates);

    expect(mockUpdate).toHaveBeenCalledWith([
      {
        id: 'rec1',
        fields: {
          'Chosen Frequency': 0,
        },
      },
    ]);

    expect(result[0].chosenFrequency).toBe(0);
  });

  it('handles multiple frequency updates in batch', async () => {
    const mockUpdatedRecords = Array.from({ length: 10 }, (_, i) => ({
      id: `rec${i}`,
