        'Service': `Service ${i}`,
        'A la Carte Rate': 100 + i * 10,
        'Handld Rate': 70 + i * 7,
        'Chosen Frequency': i + 1,
      },
    }));

    mockUpdate.mockResolvedValue(mockUpdatedRecords);

    const updates = Array.from({ length: 10 }, (_, i) => ({
      id: `rec${i}`,
      chosenFrequency: i + 1,
    }));

    const result = await updateLineItems(updates);

    expect(mockUpdate).toHaveBeenCalledTimes(1);
    expect(result).toHaveLength(10);

    // Verify all frequencies are correctly mapped
    result.forEach((item, index) => {
      expect(item.chosenFrequency).toBe(index + 1);
      expect(item.service).toBe(`Service ${index}`);
    });
  });

  it('preserves other fields when updating frequency', async () => {
    const mockUpdatedRecord = [
      {
        id: 'rec1',
        fields: {
          'Service': 'Complete Lawn Care',
          'A la Carte Rate': 250,
          'Handld Rate': 175,
          'Chosen Frequency': 6,
          'Notes': 'Includes edging and leaf removal',
          'Active': true,
        },
      },
    ];

    mockUpdate.mockResolvedValue(mockUpdatedRecord);

    const updates = [{ id: 'rec1', chosenFrequency: 6 }];

    const result = await updateLineItems(updates);

    // Verify only frequency field was sent for update
    expect(mockUpdate).toHaveBeenCalledWith([
      {
        id: 'rec1',
        fields: {
          'Chosen Frequency': 6,
        },
      },
    ]);

    // Verify returned record has all mapped fields
    expect(result[0]).toMatchObject({
      id: 'rec1',
      service: 'Complete Lawn Care',
      alaCarteRate: 250,
      handldRate: 175,
      chosenFrequency: 6,
    });
  });
});

