import { GET, PUT } from '../route';
import { NextRequest } from 'next/server';
import * as airtableModule from '@/lib/airtable';

// Mock the airtable module
jest.mock('@/lib/airtable');

describe('API Route: /api/quotes/[token]', () => {
  const mockAirtable = airtableModule as jest.Mocked<typeof airtableModule>;

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('GET /api/quotes/[token]', () => {
    it('returns quote data successfully', async () => {
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
        },
        lineItems: [
          {
            id: 'rec1',
            service: 'Lawn Mowing',
            alaCarteRate: 100,
            handldRate: 70,
            chosenFrequency: 2,
          },
        ],
      };

      mockAirtable.getQuoteByToken.mockResolvedValue(mockQuoteData);

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token');
      const response = await GET(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(mockAirtable.getQuoteByToken).toHaveBeenCalledWith('test-token');
      expect(response.status).toBe(200);
      expect(data).toEqual({
        ...mockQuoteData,
        quoteRequest: mockQuoteData.quote, // Legacy field
      });
    });

    it('returns 400 when token is missing', async () => {
      const request = new NextRequest('http://localhost:3000/api/quotes/');
      const response = await GET(request, { params: { token: '' } });
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data).toEqual({ error: 'Token is required' });
      expect(mockAirtable.getQuoteByToken).not.toHaveBeenCalled();
    });

    it('returns 404 when quote not found', async () => {
      const notFoundError = new Error('Quote not found') as any;
      notFoundError.status = 404;
      mockAirtable.getQuoteByToken.mockRejectedValue(notFoundError);

      const request = new NextRequest('http://localhost:3000/api/quotes/invalid-token');
      const response = await GET(request, { params: { token: 'invalid-token' } });
      const data = await response.json();

      expect(response.status).toBe(404);
      expect(data).toEqual({ error: 'Quote not found' });
    });

    it('returns 500 for general errors', async () => {
      mockAirtable.getQuoteByToken.mockRejectedValue(new Error('Database connection failed'));

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token');
      const response = await GET(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data).toEqual({ error: 'Database connection failed' });
    });
  });

  describe('PUT /api/quotes/[token]', () => {
    it('successfully updates line item frequencies', async () => {
      const mockQuote = {
        id: 'rec123',
        quoteId: 'Q-001',
        selectedServices: ['Lawn Mowing'],
      };

      const mockUpdatedLineItems = [
        {
          id: 'rec1',
          service: 'Lawn Mowing',
          chosenFrequency: 4,
          alaCarteRate: 100,
          handldRate: 70,
        },
      ];

      mockAirtable.updateLineItems.mockResolvedValue(mockUpdatedLineItems);
      mockAirtable.findQuoteByToken.mockResolvedValue(mockQuote);
      mockAirtable.updateQuote.mockResolvedValue(mockQuote);

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'PUT',
        body: JSON.stringify({
          lineItems: [{ id: 'rec1', chosenFrequency: 4 }],
        }),
      });

      const response = await PUT(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(mockAirtable.updateLineItems).toHaveBeenCalledWith([
        { id: 'rec1', chosenFrequency: 4 },
      ]);
      expect(response.status).toBe(200);
      expect(data).toMatchObject({
        ok: true,
        lineItems: mockUpdatedLineItems,
      });
    });

    it('handles multiple line item updates', async () => {
      const mockQuote = {
        id: 'rec123',
        quoteId: 'Q-001',
      };

      const updates = [
        { id: 'rec1', chosenFrequency: 3 },
        { id: 'rec2', chosenFrequency: 6 },
        { id: 'rec3', chosenFrequency: 12 },
      ];

      const mockUpdatedLineItems = updates.map(u => ({
        ...u,
        service: `Service ${u.id}`,
        alaCarteRate: 100,
        handldRate: 70,
