      const updatedQuote = {
        ...mockQuote,
        selectedServices: ['Lawn Mowing', 'Pool Cleaning'],
      };

      mockAirtable.findQuoteByToken.mockResolvedValue(mockQuote);
      mockAirtable.updateQuote.mockResolvedValue(updatedQuote);

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'PUT',
        body: JSON.stringify({
          selectedServices: ['Lawn Mowing', 'Pool Cleaning'],
        }),
      });

      const response = await PUT(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(mockAirtable.updateQuote).toHaveBeenCalledWith('rec123', {
        selectedServices: ['Lawn Mowing', 'Pool Cleaning'],
      });
      expect(data.quote).toEqual(updatedQuote);
      expect(response.status).toBe(200);
    });

    it('handles errors during update', async () => {
      mockAirtable.updateLineItems.mockRejectedValue(new Error('Airtable API error'));

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'PUT',
        body: JSON.stringify({
          lineItems: [{ id: 'rec1', chosenFrequency: 2 }],
        }),
      });

      const response = await PUT(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data).toEqual({ error: 'Airtable API error' });
    });

    it('handles malformed request body', async () => {
      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'PUT',
        body: 'invalid json',
      });

      const response = await PUT(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data).toHaveProperty('error');
    });

    it('processes both line items and quote updates in single request', async () => {
      const mockQuote = {
        id: 'rec123',
        quoteId: 'Q-001',
      };

      const mockUpdatedLineItems = [
        {
          id: 'rec1',
          service: 'Lawn Mowing',
          chosenFrequency: 3,
          alaCarteRate: 100,
          handldRate: 70,
        },
      ];

      const updatedQuote = {
        ...mockQuote,
        selectedServices: ['Lawn Mowing'],
      };

      mockAirtable.updateLineItems.mockResolvedValue(mockUpdatedLineItems);
      mockAirtable.findQuoteByToken.mockResolvedValue(mockQuote);
      mockAirtable.updateQuote.mockResolvedValue(updatedQuote);

      const request = new NextRequest('http://localhost:3000/api/quotes/test-token', {
        method: 'PUT',
        body: JSON.stringify({
          lineItems: [{ id: 'rec1', chosenFrequency: 3 }],
          selectedServices: ['Lawn Mowing'],
        }),
      });

      const response = await PUT(request, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(mockAirtable.updateLineItems).toHaveBeenCalled();
      expect(mockAirtable.updateQuote).toHaveBeenCalled();
      expect(data).toMatchObject({
        ok: true,
        lineItems: mockUpdatedLineItems,
        quote: updatedQuote,
      });
      expect(response.status).toBe(200);
    });
  });
});

