      .filter(update => update.id && update.chosenFrequency !== undefined)
      .map(update => ({
        id: update.id,
        fields: {
          'Chosen Frequency': update.chosenFrequency,
        },
      }));

    if (preparedUpdates.length === 0) {
      return [];
    }

    // Simulate successful update response
    return preparedUpdates.map(update => ({
      id: update.id,
      service: `Service for ${update.id}`,
      alaCarteRate: 100,
      handldRate: 70,
      chosenFrequency: update.fields['Chosen Frequency'],
    }));
