      id: `rec${i}`,
      chosenFrequency: i + 1,
    }));

    const result = await updateLineItemsLogic(updates);

    expect(result).toHaveLength(10);
    result.forEach((item, index) => {
      expect(item.chosenFrequency).toBe(index + 1);
      expect(item.id).toBe(`rec${index}`);
    });
  });

  it('validates frequency range (1-12)', async () => {
    const validateFrequency = (freq: number) => freq >= 0 && freq <= 12;

    const updates = [
      { id: 'rec1', chosenFrequency: 1 },
      { id: 'rec2', chosenFrequency: 12 },
      { id: 'rec3', chosenFrequency: 0 },
      { id: 'rec4', chosenFrequency: 6 },
    ];

    const validUpdates = updates.filter(u => validateFrequency(u.chosenFrequency));

    expect(validUpdates).toHaveLength(4);
    validUpdates.forEach(update => {
      expect(update.chosenFrequency).toBeGreaterThanOrEqual(0);
      expect(update.chosenFrequency).toBeLessThanOrEqual(12);
    });
  });

  it('maintains data integrity during updates', async () => {
    const originalData = {
      id: 'rec1',
      service: 'Lawn Mowing',
      alaCarteRate: 150,
      handldRate: 105,
      chosenFrequency: 2,
    };

    const updateRequest = { id: 'rec1', chosenFrequency: 4 };

    // Simulate update that preserves other fields
    const result = {
      ...originalData,
      chosenFrequency: updateRequest.chosenFrequency,
    };

    expect(result.service).toBe('Lawn Mowing');
    expect(result.alaCarteRate).toBe(150);
    expect(result.handldRate).toBe(105);
    expect(result.chosenFrequency).toBe(4);
  });

  it('handles concurrent updates correctly', async () => {
    const updates1 = [{ id: 'rec1', chosenFrequency: 3 }];
    const updates2 = [{ id: 'rec2', chosenFrequency: 5 }];

    const [result1, result2] = await Promise.all([
      updateLineItemsLogic(updates1),
      updateLineItemsLogic(updates2),
    ]);

    expect(result1).toHaveLength(1);
    expect(result2).toHaveLength(1);
    expect(result1[0].id).toBe('rec1');
    expect(result2[0].id).toBe('rec2');
  });
});

