import React from 'react';
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import QuoteViewerPage from '../page';
import { useToast } from '@/components/ui/use-toast';

// Mock dependencies
jest.mock('next/navigation', () => ({
  useParams: jest.fn(),
  useSearchParams: jest.fn(),
}));

jest.mock('@/components/ui/use-toast', () => ({
  useToast: jest.fn(),
}));

jest.mock('../../../components/LineItemsTable', () => {
  return function MockLineItemsTable({ 
    lineItems, 
    loadingItems, 
    onFrequencyChange 
  }: any) {
    return (
      <div data-testid="line-items-table">
        {lineItems.map((item: any) => (
          <div key={item.id}>
            <span>{item.service}</span>
            <button 
              onClick={() => onFrequencyChange?.(item.id, 3)}
              disabled={loadingItems?.has(item.id)}
            >
              Change Frequency
            </button>
            {loadingItems?.has(item.id) && <span>Loading...</span>}
          </div>
        ))}
      </div>
    );
  };
});

// Mock fetch
global.fetch = jest.fn();

describe('QuoteViewerPage - Frequency Update', () => {
  const mockToast = jest.fn();
  const mockQuoteData = {
    quote: {
      id: 'rec123',
      quoteId: 'Q-001',
      firstName: 'John',
      lastName: 'Doe',
      email: 'john@example.com',
      city: 'Austin',
      stories: '2',
      squareFootage: '2500',
      lotSize: '0.25 acres',
    },
    lineItems: [
      {
        id: 'rec1',
        service: 'Lawn Mowing',
        alaCarteRate: 100,
        handldRate: 70,
        chosenFrequency: 2,
        requestLink: ['req1'],
      },
      {
        id: 'rec2',
        service: 'Pool Cleaning',
        alaCarteRate: 150,
        handldRate: 105,
        chosenFrequency: 4,
        requestLink: ['req1'],
      },
    ],
  };

  beforeEach(() => {
    jest.clearAllMocks();

    (useToast as jest.Mock).mockReturnValue({ toast: mockToast });

    const mockUseParams = require('next/navigation').useParams;
    const mockUseSearchParams = require('next/navigation').useSearchParams;

    mockUseParams.mockReturnValue({ token: 'test-token' });
    mockUseSearchParams.mockReturnValue(new URLSearchParams());

    (global.fetch as jest.Mock).mockResolvedValue({
      ok: true,
      json: async () => mockQuoteData,
    });
  });

  it('handles successful frequency update', async () => {
    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Mock successful API response
    (global.fetch as jest.Mock).mockImplementationOnce(() => 
      Promise.resolve({
        ok: true,
        json: async () => ({ ok: true }),
      })
    );

    // Click to change frequency
    const changeButtons = screen.getAllByText('Change Frequency');

    await act(async () => {
      fireEvent.click(changeButtons[0]);
    });

    // Wait for the update to complete
    await waitFor(() => {
      expect(mockToast).toHaveBeenCalledWith({
        title: 'Success',
        description: 'Frequency updated successfully',
        variant: 'success',
      });
    });

    // Verify API was called with correct data
    expect(global.fetch).toHaveBeenCalledWith(
      '/api/quotes/test-token',
      {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineItems: [{ id: 'rec1', chosenFrequency: 3 }],
        }),
      }
    );
  });

  it('handles failed frequency update with rollback', async () => {
    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Mock failed API response
