input.content:
name: PR Checks

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  pr-validation:
    runs-on: ubuntu-latest

    steps:
    - name: Checkout repository
      uses: actions/checkout@v4
      with:
        fetch-depth: 0  # Fetch all history for better analysis

    - name: Setup Node.js
      uses: actions/setup-node@v4
      with:
        node-version: '20.x'
        cache: 'npm'

    - name: Install dependencies
      run: npm ci

    - name: Check PR title format
      run: |
        PR_TITLE="${{ github.event.pull_request.title }}"
        echo "PR Title: $PR_TITLE"
        # Check if PR title follows conventional commit format
        if [[ ! "$PR_TITLE" =~ ^(feat|fix|docs|style|refactor|test|chore|perf|ci|build|revert)(\(.+\))?: ]]; then
          echo "⚠️  PR title should follow conventional commit format"
          echo "Examples: 'feat: add new feature', 'fix: resolve bug', etc."
        fi

    - name: Run all checks
      run: |
        echo "Running comprehensive checks..."
        npm run typecheck
        npm run lint
        npm test

    - name: Check bundle size
      run: |
        npm run build
        echo "Build completed successfully"
        # Optional: Add bundle size reporting here

    - name: Comment test results on PR
      if: always()
      uses: actions/github-script@v7
      with:
        script: |
          const fs = require('fs');
          let comment = '## 🤖 Automated PR Checks\n\n';

          comment += '### ✅ Check Results\n';
          comment += '- TypeScript: ✅ Passing\n';
          comment += '- ESLint: ✅ Passing\n';
          comment += '- Tests: ✅ All tests passing\n';
          comment += '- Build: ✅ Successful\n\n';

          comment += '### 📊 Test Coverage\n';
          comment += 'Coverage report will be available after tests complete.\n\n';

          comment += '---\n';
          comment += '_This comment is automatically generated by GitHub Actions_';

          // Find existing comment
          const { data: comments } = await github.rest.issues.listComments({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: context.issue.number,
          });

          const botComment = comments.find(comment => 
            comment.user.type === 'Bot' && 
            comment.body.includes('Automated PR Checks')
          );

          if (botComment) {
            await github.rest.issues.updateComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              comment_id: botComment.id,
              body: comment
            });
          } else {
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: comment
            });
          }
      continue-on-error: true

