// Airtable configuration constants
// These are not sensitive and should be kept in sync with your Airtable schema

export const AIRTABLE_CONFIG = {
  // Table names
  QUOTES_TABLE: 'Quote Requests',
  LINE_ITEMS_TABLE: 'Quote Line Items',

  // Field names
  TOKEN_FIELD: 'Token',
  LINK_FIELD: 'Quote Request',
  QUOTE_ID_LOOKUP_FIELD: 'Quote ID (from Request)',

  // Common field names
  FIELDS: {
    // Quote fields
    QUOTE_ID: 'Quote ID',
    FIRST_NAME: 'First Name',
    LAST_NAME: 'Last Name',
    EMAIL: 'Email',
    CITY: 'City',
    STORIES: 'Stories',
    SQUARE_FOOTAGE: 'Square Footage',
    LOT_SIZE: 'Lot Size',
    A_LA_CARTE_TOTAL: 'A La Carte Total',
    HANDLD_TOTAL: 'Handld Total',
    A_LA_CARTE_TOTAL_ANNUAL: 'A La Carte Total Annual',
    HANDLD_TOTAL_ANNUAL: 'Handld Total Annual',
    SELECTED_SERVICES: 'Selected Services',
    CREATED_AT: 'Created At',
    UPDATED_AT: 'Updated At',

    // Line item fields
    SERVICE: 'Service',
    DESCRIPTION: 'Description',
    HANDLD_RATE: 'Handld Rate',
    A_LA_CARTE_RATE: 'A La Carte Rate',
    CHOSEN_FREQUENCY: 'Chosen Frequency',
    UNIT: 'Unit',
    LINK_TO_QUOTE: 'Link to Quote Request',
  }
} as const;

// Type-safe table names
export type TableName = typeof AIRTABLE_CONFIG.QUOTES_TABLE | typeof AIRTABLE_CONFIG.LINE_ITEMS_TABLE;

// Type-safe field names
export type QuoteFieldName = keyof typeof AIRTABLE_CONFIG.FIELDS;

// Helper functions for backward compatibility with existing code
export const getTableName = (type: 'quotes' | 'lineItems' | string): string => {
  switch(type) {
    case 'quotes': return AIRTABLE_CONFIG.QUOTES_TABLE;
    case 'lineItems': return AIRTABLE_CONFIG.LINE_ITEMS_TABLE;
    default: return type;
  }
};

export const getFieldName = (field: string): string => {
  return (AIRTABLE_CONFIG.FIELDS as any)[field] || field;
};

